      return '<button class="quiz-option '+(right?"correct":"")+' '+(wrong?"incorrect":"")+'" data-match-choice="'+escapeHTML(option.fi)+'" '+(answered?"disabled":"")+'>'+escapeHTML(option.fi)+'</button>';
