  function speakingMatches(heard,target){
    const normalize=value=>String(value||'').toLocaleLowerCase('fi-FI').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(Boolean);
    const words=normalize(heard),targetWords=normalize(target);return targetWords.length>0&&targetWords.every(word=>words.includes(word));
  }
  function stopSpeakingRecognition(){
    const recognition=state.speakingRecognition;state.speakingRecognition=null;state.speakingListening=false;
    if(recognition){try{recognition.abort()}catch(_error){}}
  }
  function startSpeakingRecognition(){
    const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
    if(!Recognition){state.speakingError='unsupported';renderSpeaking();return}
    stopSpeakingRecognition();state.speakingTranscript='';state.speakingMatch=false;state.speakingError='';
    const recognition=new Recognition(),course=speakingPractice[state.speakingLevel],step=Math.min(Number(state.speakingSteps[state.speakingLevel]||0),course.items.length-1),target=course.items[step].fi;
    recognition.lang='fi-FI';recognition.continuous=false;recognition.interimResults=false;recognition.maxAlternatives=1;
    state.speakingRecognition=recognition;state.speakingListening=true;renderSpeaking();
    recognition.onresult=event=>{if(state.speakingRecognition!==recognition)return;state.speakingTranscript=event.results?.[0]?.[0]?.transcript||'';state.speakingMatch=state.speakingLevel==="b2"||state.speakingLevel==="c1"?false:speakingMatches(state.speakingTranscript,target);state.speakingError=''};
    recognition.onerror=event=>{if(state.speakingRecognition!==recognition)return;state.speakingError=event.error==='not-allowed'||event.error==='service-not-allowed'||event.error==='audio-capture'?'permission':event.error==='network'?'network':event.error==='language-not-supported'?'language':event.error==='no-speech'?'noSpeech':'generic'};
    recognition.onend=()=>{if(state.speakingRecognition!==recognition)return;state.speakingRecognition=null;state.speakingListening=false;if(state.page==='speaking')renderSpeaking()};
    try{recognition.start()}catch(_error){state.speakingRecognition=null;state.speakingListening=false;state.speakingError='generic';renderSpeaking()}
  }
