    const speechAvailable="speechSynthesis" in window&&"SpeechSynthesisUtterance" in window;
    const heading=`<div class="page-title-row"><div><div class="page-kicker">PRE-A1 · LISTEN FOR MEANING</div><h1>Listen & understand</h1><p>${isC1?"Follow longer Finnish talks with careful qualifications and implied points. Decide which interpretation the full talk supports.":isB2?"Follow longer Finnish arguments about city life, nature, and work. Identify the main claim, the reasons behind it, and what the speaker really supports.":isB1?"Listen to connected Finnish about work, plans, and everyday life. Follow the main idea, then notice a key detail.":"Hear a short Finnish phrase, picture the moment, and choose what it means."}</p></div><span class="cafe-level-pill">${isC1?"C1 · LONGER TALKS":isB2?"B2 · LONGER TALKS":activeItems.length+" SHORT ROUNDS"}</span></div>`;
    const pageHeading=heading.replace("PRE-A1 · LISTEN FOR MEANING",isC1?"C1 · FOLLOW COMPLEX SPEECH":isB2?"B2 · FOLLOW ARGUMENTS & ATTITUDES":isB1?"B1 · FOLLOW CONNECTED SPEECH":isA2?"A2 · FOLLOW EVERYDAY STORIES":isA1?"A1 · LISTEN FOR MEANING":"PRE-A1 · LISTEN FOR MEANING");
    const levelPicker='<div class="listening-level-picker" role="tablist" aria-label="Listening level"><button class="listening-level-tab '+(!isA1&&!isA2&&!isB1&&!isB2&&!isC1?"selected":"")+'" role="tab" aria-selected="'+(!isA1&&!isA2&&!isB1&&!isB2&&!isC1)+'" data-listening-level="pre-a1"><span>Foundation</span><small>'+(state.listeningComplete?"3 / 3 complete":"Pre-A1 · first phrases")+'</small></button><button class="listening-level-tab '+(isA1?"selected":"")+'" role="tab" aria-selected="'+isA1+'" data-listening-level="a1"><span>A1 next steps</span><small>'+(state.a1ListeningComplete?"3 / 3 complete":"A1 · useful phrases")+'</small></button><button class="listening-level-tab '+(isA2?"selected":"")+'" role="tab" aria-selected="'+isA2+'" data-listening-level="a2"><span>A2 stories</span><small>'+(state.a2ListeningComplete?"3 / 3 complete":"A2 · key details")+'</small></button><button class="listening-level-tab '+(isB1?"selected":"")+'" role="tab" aria-selected="'+isB1+'" data-listening-level="b1"><span>B1 connected speech</span><small>'+(state.b1ListeningComplete?"3 / 3 complete":"B1 · main idea & detail")+'</small></button><button class="listening-level-tab '+(isB2?"selected":"")+'" role="tab" aria-selected="'+isB2+'" data-listening-level="b2"><span>B2 longer talks</span><small>'+(state.b2ListeningComplete?"3 / 3 complete":"Claims · reasons · views")+'</small></button><button class="listening-level-tab '+(isC1?"selected":"")+'" role="tab" aria-selected="'+isC1+'" data-listening-level="c1"><span>C1 nuanced talks</span><small>'+(state.c1ListeningComplete?"3 / 3 complete":"Implication · qualification")+'</small></button></div>';
    const doneMarkup=`<section class="listening-complete"><div class="listening-complete-mark">✓</div><div class="listening-complete-copy"><span class="review-kicker">NICE LISTENING</span><h2>${isC1?"You followed the implied points, careful qualifications, and speaker’s views across three advanced talks.":isB2?"You followed the claim, supporting reasons, and speaker’s view across three longer talks.":isB1?"You followed the main ideas and key details in three connected stories.":isA2?"You caught the key details in three longer stories.":"You understood all three moments."}</h2><p>${isC1?"You listened across energy, culture, and public services, using the whole talk to interpret the speaker’s meaning.":isB2?"You weighed competing ideas about transport, nature tourism, and remote work.":isB1?"You listened for reasons, changes in plans, and how events connect.":isA2?"You listened for times, days, travel details, and weekend plans.":"Each replay helps your ear get used to the rhythm of Finnish."} Come back whenever you want another listen.</p><button class="button-secondary" data-listening-action="restart">Listen again <span>↻</span></button></div><div class="listening-complete-art" aria-hidden="true">🌲<span>❄️</span></div></section>`;
    const a2Resources=`<section class="listening-real-world"><div><span class="review-kicker">REAL FINNISH · VIDEO & DIALOGUE</span><h2>Hear Finnish in everyday service situations</h2><p>Yle’s Asiointisuomea videos cover places such as cafés, shops, libraries, and health centres. The videos are labeled A2.1–B2.1, with written dialogues below them.</p></div><a class="button-secondary" href="https://yle.fi/a/20-146213" target="_blank" rel="noreferrer">Watch a Yle video ↗</a></section><div class="listening-sources">This A2 practice focuses on clear, familiar speech and key details, following the <a href="https://www.oph.fi/sites/default/files/documents/169247_proficiency_levels_cefr.pdf" target="_blank" rel="noreferrer">Finnish National Agency for Education’s A2 listening description ↗</a>. Video and dialogue resource: <a href="https://yle.fi/a/20-146213" target="_blank" rel="noreferrer">Yle Asiointisuomea ↗</a>.</div>`;
    const b1Resources=`<section class="listening-real-world"><div><span class="review-kicker">REAL FINNISH · CLEAR NEWS</span><h2>Try a short story from Yle Selkouutiset</h2><p>Listen for the main point first, then notice a person, reason, or detail that explains the story. These lessons use your browser’s Finnish voice; Yle provides recorded Finnish.</p></div><a class="button-secondary" href="https://yle.fi/selkouutiset" target="_blank" rel="noreferrer">Listen to Yle news ↗</a></section><div class="listening-sources">B1.1 goal: understand main ideas and some details in clear, near-normal-speed standard speech, following <a href="https://www.oph.fi/fi/koulutus-ja-tutkinnot/kehittyvan-kielitaidon-tasojen-kuvausasteikko" target="_blank" rel="noreferrer">OPH’s developing language proficiency scale ↗</a>.</div>`;
    const c1Resources=`<section class="listening-real-world"><div><span class="review-kicker">AUTHENTIC · NATURAL FINNISH</span><h2>Explore longer Finnish programmes</h2><p>Try an unscripted Yle Areena podcast or discussion. Listen once for the broad point, then again for qualifications, shifts in register, and what the speaker leaves implicit. The practice above uses your browser’s Finnish voice.</p></div><a class="button-secondary" href="https://areena.yle.fi/podcastit" target="_blank" rel="noreferrer">Explore Yle Areena podcasts ↗</a></section><div class="listening-sources">C1.1 listening goal: understand longer speech on unfamiliar subjects even when its structure is not fully explicit, including idiomatic language and shifts in register. These focused, browser-voiced exercises are not an official YKI task. <a href="https://www.oph.fi/sites/default/files/documents/language-proficiency-scale_finnish-and-swedish-as-a-second-language-and-literature.pdf" target="_blank" rel="noreferrer">Read OPH’s Finnish proficiency scale ↗</a>.</div>`;
