    if(complete){const summary=isB2?"You practised conditional suggestions, the present passive, the zero-person pattern, and plural partitive forms.":isB1?"You practised relative clauses, the perfect tense, contrast, and purpose.":isA2?"You practised the imperfect, place direction, polite requests, and because.":isA1?"You practised negative sentences, vowel harmony, the partitive, and question words.":"You practised verb endings, place words, possession, and yes/no questions.";pageContent.innerHTML=heading+levelPicker+`<section class="grammar-complete"><div class="grammar-complete-mark">✓</div><span class="review-kicker">${levelName.toUpperCase()} · COMPLETE</span><h2>You explored four ${levelName} grammar patterns.</h2><p>${summary} Revisit any time for a refresher.</p><button class="button-secondary" data-grammar-action="restart">Review ${levelName} lessons <span>↻</span></button><div class="grammar-complete-art" aria-hidden="true">✦</div></section>`;return}
    const progress=Math.round(((state.grammarStep+1)/activeLessons.length)*100);
    const chips=item.pattern.map((part,index)=>`<div class="grammar-pattern-chip ${index===item.pattern.length-1?"emphasis":""}"><strong>${escapeHTML(part.fi)}</strong><small>${escapeHTML(part.gloss)}</small></div>${index<item.pattern.length-1?`<span class="grammar-pattern-arrow" aria-hidden="true">${item.pattern.length===3&&index===0?"+":"→"}</span>`:""}`).join("");
    const choices=item.choices.map((choice,index)=>`<button class="grammar-choice ${state.grammarAnswered&&index===item.answer?"correct":""} ${state.grammarAnswered&&index===state.grammarChoice&&index!==item.answer?"incorrect":""}" data-grammar-choice="${index}" ${state.grammarAnswered?"disabled":""}><span class="grammar-choice-letter">${String.fromCharCode(65+index)}</span><span><strong>${escapeHTML(choice.fi)}</strong><small>${escapeHTML(state.help==="bn"?choice.bn:choice.en)}</small></span></button>`).join("");
