    if(isB1){pageContent.querySelector(".grammar-sources").innerHTML=`B1.1 learning goal: <a href="https://www.oph.fi/fi/koulutus-ja-tutkinnot/kehittyvan-kielitaidon-tasojen-kuvausasteikko" target="_blank" rel="noreferrer">OPH language-skill descriptors ↗</a>. Grammar checked with <a href="https://uusikielemme.fi/finnish-grammar/syntax/constructions/the-relative-pronoun-joka-joka-pronomini" target="_blank" rel="noreferrer">relative pronouns ↗</a>, <a href="https://uusikielemme.fi/finnish-grammar/verbs/verb-tenses-and-moods/the-perfect-tense-perfekti" target="_blank" rel="noreferrer">the perfect tense ↗</a>, and <a href="https://uusikielemme.fi/finnish-grammar/syntax/sentence-types/sivulause-finnish-sentence-types-subordinate-clauses" target="_blank" rel="noreferrer">subordinate clauses ↗</a>. Audio uses the Finnish voice available in your browser.`}
    if(isB2){pageContent.querySelector(".grammar-sources").innerHTML=`B2.1 calls for clear, precise expression with varied structures. Aalto’s Finnish 3B course objectives list conditional mood, present passive, zero-person constructions, and plural cases; these lessons apply those patterns to Finnish transport, nature, and decision-making contexts. <a href="https://www.oph.fi/fi/koulutus-ja-tutkinnot/kehittyvan-kielitaidon-tasojen-kuvausasteikko" target="_blank" rel="noreferrer">OPH proficiency scale ↗</a> · <a href="https://www.aalto.fi/sites/default/files/2019-09/aalto_avoin_2018_kesa_0.pdf#page=129" target="_blank" rel="noreferrer">Aalto Finnish 3B course objectives ↗</a>. This is focused practice, not a complete B2 grammar syllabus.`}
